<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {buildAgriculture} from '../scenes/agriculture';
import {buildIndustry} from '../scenes/industry';
import {buildPark} from '../scenes/park';
const props=defineProps({kind:String,rotate:Boolean,running:{type:Boolean,default:true},layer:{default:'all'},view:{default:'perspective'},zoom:{default:0},reset:{default:0}});
const emit=defineEmits(['select']);const host=ref(null),labels=ref([]),failed=ref(false);let renderer,scene,camera,controls,model,observer,frame,visible=true,last=0,t=0,labelTime=0;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function resetCamera(){if(!model)return;camera.position.fromArray(model.home);controls.target.fromArray(model.target);controls.update()}
function handleLost(e){e.preventDefault();failed.value=true;cancelAnimationFrame(frame)}
function handleVisibility(){visible=!document.hidden;last=0}
onMounted(()=>{try{scene=new THREE.Scene();const farm=props.kind==='agriculture';scene.fog=new THREE.FogExp2(farm?'#0e211b':'#11171e',.009);camera=new THREE.PerspectiveCamera(38,1,.1,160);
renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(window.devicePixelRatio,1.5));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=farm?1.55:1.65;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;host.value.prepend(renderer.domElement);renderer.domElement.addEventListener('webglcontextlost',handleLost);
scene.add(new THREE.HemisphereLight(farm?'#ddf5df':'#dce7f0',farm?'#263c26':'#343441',2.7));const key=new THREE.DirectionalLight(farm?'#ffefd0':'#eaf4ff',3.8);key.position.set(8,28,12);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-23;key.shadow.camera.right=23;key.shadow.camera.top=23;key.shadow.camera.bottom=-23;key.shadow.camera.far=85;key.shadow.normalBias=.06;scene.add(key);const rim=new THREE.DirectionalLight(farm?'#62d9a9':'#ffb565',2.3);rim.position.set(-18,8,-12);scene.add(rim);
const grid=new THREE.GridHelper(100,50,farm?'#355548':'#384047',farm?'#1b382f':'#222d38');grid.position.y=-1.4;grid.material.transparent=true;grid.material.opacity=.35;scene.add(grid);
model=farm?buildAgriculture(scene):props.kind==='park'?buildPark(scene):buildIndustry(scene);model.setLayer(props.layer);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.055;controls.minDistance=28;controls.maxDistance=90;controls.maxPolarAngle=Math.PI*.46;controls.minPolarAngle=.15;controls.enablePan=false;controls.autoRotateSpeed=.6;resetCamera();model.update(0,true);
observer=new ResizeObserver(()=>{const {width,height}=host.value.getBoundingClientRect();if(!width||!height)return;camera.aspect=width/height;camera.updateProjectionMatrix();renderer.setSize(width,height)});observer.observe(host.value);document.addEventListener('visibilitychange',handleVisibility);
function draw(now){frame=requestAnimationFrame(draw);if(!visible)return;if(last&&now-last<32)return;const delta=last?Math.min((now-last)/1000,.08):0;last=now;if(props.running&&!reduced)t+=delta;model.update(t,props.running&&!reduced);controls.autoRotate=props.rotate&&!reduced;controls.update();renderer.render(scene,camera);
if(now-labelTime>80){labelTime=now;const w=host.value.clientWidth,h=host.value.clientHeight;labels.value=model.labels.map((l,i)=>{const p=l.position.clone().project(camera);return {...l,id:i,x:(p.x+1)*w/2,y:(1-p.y)*h/2,visible:p.z<1&&Math.abs(p.x)<.92&&Math.abs(p.y)<.85}})}}frame=requestAnimationFrame(draw);
}catch(e){failed.value=true;console.warn('3D scene initialization failed',e)}});
watch(()=>props.layer,v=>model?.setLayer(v));watch(()=>props.zoom,(v,old)=>{if(!camera)return;const direction=camera.position.clone().sub(controls.target);direction.multiplyScalar(v>old?.86:1.16).clampLength(28,90);camera.position.copy(controls.target).add(direction)});watch(()=>props.reset,resetCamera);
watch(()=>props.view,v=>{if(!camera)return;camera.position.set(...(v==='top'?[.1,58,.1]:model.home));controls.target.set(0,0,0);controls.update()});
onBeforeUnmount(()=>{cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();document.removeEventListener('visibilitychange',handleVisibility);renderer?.domElement.removeEventListener('webglcontextlost',handleLost);const geometries=new Set(),materials=new Set();scene?.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>materials.add(m))});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());renderer?.dispose()});
</script>
<template><div ref="host" class="scene-viewport" :class="kind"><div v-if="failed" class="scene-error">三维场景暂时无法显示<small>请启用浏览器硬件加速后刷新页面</small></div><template v-else><button v-for="l in labels.filter(l=>l.visible)" :key="l.id" class="scene-pin" :style="{left:l.x+'px',top:l.y+'px'}" @click="emit('select',l)"><span class="pin-dot"></span><span>{{l.name}}</span><span class="pin-plus">+</span></button></template></div></template>
<style scoped>
.scene-viewport{position:absolute;inset:0;overflow:hidden}.scene-viewport:deep(canvas){display:block;width:100%;height:100%;touch-action:none;cursor:grab}.scene-viewport:deep(canvas:active){cursor:grabbing}.scene-pin{position:absolute;transform:translate(-50%,-100%);display:flex;align-items:center;gap:7px;padding:7px 10px;border:1px solid #99c59266;background:#172a22df;color:#d4e7cc;border-radius:5px;font-size:10px;white-space:nowrap;box-shadow:0 5px 14px #0003;backdrop-filter:blur(8px)}.scene-pin:after{content:'';position:absolute;left:50%;top:100%;height:15px;width:1px;background:#a7c58a99}.pin-dot{width:4px;height:4px;border-radius:50%;background:#d9db99;box-shadow:0 0 6px #c9e9a4}.pin-plus{color:#adc692;margin-left:3px}.industry .scene-pin{border-radius:0;color:#d9e0e3;background:#1b232bed;border-color:#ad7d4144;font-family:monospace;border-left:2px solid #e6a951}.industry .pin-dot{background:#ffa951}.industry .scene-pin:after{background:#cc995277}.industry .pin-plus{color:#f1ae51}.scene-pin:hover{background:#294035;color:#fff}.industry .scene-pin:hover{background:#3a3026}.scene-pin:focus-visible{outline:2px solid #dddaa3;outline-offset:3px}.scene-error{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#a7bcb3;font-size:14px}.scene-error small{font-size:11px;margin-top:10px}
@media(max-width:650px){.scene-pin{font-size:8px;padding:5px 6px;gap:4px}}
</style>
